<?php $year=get_post_meta(get_the_ID(),'_p69_release_year',true); $poster=get_the_post_thumbnail_url(get_the_ID(),'medium_large'); if(!$poster){$poster=esc_url(get_post_meta(get_the_ID(),'_p69_tmdb_poster_url',true));} if(!$poster){$poster=esc_url(get_post_meta(get_the_ID(),'_p69_original_poster_url',true));} ?><article <?php post_class('movie-card'); ?>><a class="poster-wrap" href="<?php the_permalink(); ?>"><?php if($poster): ?><img src="<?php echo esc_url($poster); ?>" alt="<?php echo esc_attr(get_the_title()); ?>" loading="lazy" decoding="async"><?php else: ?><span class="poster-placeholder"><b>P69</b><small>POSTER PENDING</small></span><?php endif; ?><span class="poster-type"><?php $type=get_post_type_object(get_post_type()); echo esc_html($type ? $type->labels->singular_name : 'Title'); ?></span></a><div class="card-meta"><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><?php if($year): ?><span><?php echo esc_html($year); ?></span><?php endif; ?></div></article>